#!/usr/bin/env python3
"""Refuses an empty report and any requirement that is not a plain index version."""

import json
import re
import sys
from typing import Any

HEADER = (
    "# Generated by scripts/compile-mcp-tools-requirements.sh. Do not edit by hand:\n"
    "# Dependabot bumps single pins, the script regenerates the whole list.\n"
)


def canonical(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()


def pins_from_report(report: dict[str, Any]) -> list[str]:
    installs: list[dict[str, Any]] = report.get("install", [])
    if not installs:
        raise ValueError("the report lists nothing to install")
    pins: dict[str, str] = {}
    for item in installs:
        if item.get("is_direct"):
            url = item.get("download_info", {}).get("url", "?")
            raise ValueError(f"direct URL requirement: {url}")
        metadata = item["metadata"]
        pins[canonical(metadata["name"])] = metadata["version"]
    return [f"{name}=={version}" for name, version in sorted(pins.items())]


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print("usage: report_to_pins.py REPORT.json", file=sys.stderr)
        return 2
    with open(argv[1]) as handle:
        report = json.load(handle)
    try:
        pins = pins_from_report(report)
    except ValueError as error:
        print(f"ERROR: {error}", file=sys.stderr)
        return 1
    sys.stdout.write(HEADER + "\n".join(pins) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
